customCss:
/* Boulayla design-system touches */
.preview h1 { letter-spacing: -0.015em; }
.preview h2, .preview h3 { letter-spacing: -0.01em; }
.preview h4, .preview h5, .preview h6 { letter-spacing: -0.005em; }
.preview pre { border-radius: 6px; }
.preview :not(pre) > code { border-radius: 4px; }
.preview table { font-variant-numeric: tabular-nums; }
.preview blockquote { border-left-width: 3px; }
